def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    # Check if the file exists and is readable
    if os.path.exists(file_name) and not os.access(file_name, os.R_OK | os.W_OK | os.X_OK):
        raise ValueError("File {} not readable or cannot be created".format(file_name))
    # Create the file if it doesn't exist
    if not os.path.exists(file_name):
        open(file_name, 'w').close()
    # Append the text to the file
    with open(file_name, 'a' if overwrite else 'r+') as f:
        f.write(text_buffer.encode(encoding))
    return len(text_buffer)

