def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if coord in self.__class__.HIST_RANGE:
        self.hist[coord] += weight

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if coord[0] < self.edges[0] or coord[0] > self.edges[-1]:
            return
        if self._density is None:
            self._density = np.zeros_like(self.edges)
        if weight == 1:
            self._density[coord[0]] += 1
        else:
            self._density[coord[0]] += weight
        self._density = np.maximum(self._density, 0)
        self._norm = None

    def normalize(self):
        """Normalize the histogram, so it sums to 1."""
        if self._density is None:
            return
        self._norm = np.linalg.norm(self._density)
        self._density = self._density / self._norm

    def plot(self, ax=None, **kwargs):
        """Plot the histogram with matplotlib."""
        if ax is None:
            fig, ax = plt.subplots()
        ax.bar(self.edges.midpoints(bounded=True), self.density, **kwargs)
        ax.set_xlabel(self.xlabel)
        ax.set_ylabel(self.ylabel)
        return ax

def fill(self, coord, weight=1):
    """Fill histogram with the given weight.

    Coordinates outside the histogram edges are ignored.
    """
    if weight <= 0:
        return
    if not self.histogram:
        raise ValueError("Cannot fill histogram, it is not initialized.")
    if not isinstance(coord, tuple):
        raise ValueError("Coordinate must be a tuple of integers.")
    if len(coord) != self.nbins:
        raise ValueError("Coordinate must have the same length as the number of bins.")
    for i, c in enumerate(coord):
        if c < 0 or c >= self.edges[i].size:
            return
    self.histogram[coord] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("coord must be a 2-tuple of integers")
    if not isinstance(weight, int):
        raise ValueError("weight must be an integer")

    x, y = coord
    if x < 0 or x >= self.n_bins or y < 0 or y >= self.n_bins:
        return

    self.histogram[x][y] += weight

    if self.normalize:
        self.histogram_norm[x][y] += weight

