def _validate_labels(labels):
	"""
	Check that keys and values in the given labels match against their corresponding regular expressions.

	Args:
		labels (dict): The different labels to validate.

	Raises:
		ValidationError: If any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
		- key: The label key or label value for which an error occurred as string.
		- value: The error message.

		.. code:: python

		# Example:
		labels = {
			"key1": "valid",
			"key2": ["invalid"],
			"$$": "invalid",
			True: True,
		}
		try:
			_validate_labels(labels)
		except ValidationError as err:
			assert err.messages == [
				{"['invalid']": 'expected string or bytes-like object'},
				{'$$': "Label key '$$' does not match the regex [...]"},
				{'True': 'expected string or bytes-like object'},
				{'True': 'expected string or bytes-like object'},
			]
	"""
	validation_errors = []
	for key, value in labels.items():
		# Check if key matches the regex for label keys
		if not re.match(r'^[a-zA-Z0-9_]+$', key):
			validation_errors.append({key: "Label key '%s' does not match the regex '%s'" % (key, re.match)})
		# Check if value matches the regex for label values
		if isinstance(value, str):
			if not re.match(r'^[a-zA-Z0-9_]+$', value):
				validation_errors.append({key: "Label value '%s' does not match the regex '%s'" % (value, re.match)})
			else:
				validation_errors.append({key: "expected string or bytes-like object"})
		elif isinstance(value, list):
			for v in value:
				if not re.match(r'^[a-zA-Z0-9_]+$', v):
					validation_errors.append({key: "Label value '%s' does not match the regex '%s'" % (v, re.match)})
				else:
					validation_errors.append({key: "expected string or bytes-like object"})
		else:
			validation_errors.append({key: "expected string or bytes-like object"})

	if validation_errors:
		raise ValidationError(message=", ".join(str(error) for error in validation_errors))

