def _explore_zipfile(zip_path):
    """
    Gets packages' data from zip_path.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary with the following format:
            {
                "original" : {
                    "path": "/path/to/original/file",
                    "content": "<xml>content</xml>",
                    "metadata": {
                        "source": "original",
                        "by": "10.5281/zenodo.12345",
                        "date": "2022-01-01T00:00:00Z"
                    }
                }
                "translated" : {
                    "path": "/path/to/translated/file",
                    "content": "<xml>content</xml>",
                    "metadata": {
                        "source": "translated",
                        "by": "10.5281/zenodo.67890",
                        "date": "2022-01-01T00:00:00Z"
                    }
                }
            }
    """
    def _get_xml_basename(path):
        return os.path.basename(path).rsplit('.', 1)[0]

    def _read_zipfile(zip, file):
        return zip.read(file.filename).decode('utf-8')

    def _get_metadata(contents, source):
        soup = BeautifulSoup(contents, 'xml')
        title = soup.find('title')
        authors = soup.find_all('author')
        date = soup.find('date')
        return {
            "source": source,
            "by": "10.5281/zenodo.12345" if source == 'original' else "10.5281/zenodo.67890",
            "title": title.text.strip() if title else None,
            "authors": [author.text.strip() for author in authors] if authors else None,
            "date": date.text.strip() if date else None
        }

    with ZipFile(zip_path) as zip:
        files = [file for file in zip.infolist() if file.filename.lower().endswith('.xml')]

        data = {}
        for file in files:
            # Get the XML basename
            basename = _get_xml_basename(file.filename)

            # Read the XML file
            try:
                contents = _read_zipfile(zip, file)
            except Exception as e:
                print(f"Unable to read file {file.filename}")
                continue

            # Get the metadata
            metadata = _get_metadata(contents, basename)

            # Add the data to the dictionary
            data[basename] = {
                "path": file.filename,
                "content": contents,
                "metadata": metadata
            }

    return data

def _explore_zipfile(zip_path):
