def absorb(self, args):
    # Apply absorption and negative absorption
    # See https://en.wikipedia.org/wiki/Absorption_law
    if len(args) == 0:
        return []
    result = [args[0]]
    for i in range(1, len(args)):
        expr = args[i]
        if expr in result:
            # Absorption: A & (A | B) = A
            result = [expr]
        else:
            if isinstance(expr, list):
                # Negative absorption: A & (~A | B) = A & B
                result.extend(expr)
            else:
                # Add the expression to the result
                result.append(expr)
    return result

