def render(pieces, style):
    """Render the given version pieces into the requested style.

    Arguments:
        pieces (list): List of version pieces to be rendered.
        style (str): The style in which the version should be rendered.
            Acceptable values for style are:
            - "major": Render only the major version number (e.g., "1" for "1.2.3").
            - "major.minor": Render the major and minor version numbers (e.g., "1.2" for "1.2.3").
            - "semver": Render the version in the Semantic Versioning format (e.g., "1.2.3" for "1.2.3").

    Returns:
        str: The version string in the requested format.
    """
    # Check if the given style is acceptable.
    if style not in ["major", "major.minor", "semver"]:
        raise ValueError("Unsupported style: " + style)

    # Extract the version parts.
    pieces_dict = {}
    for piece in pieces:
        pieces_dict[piece["type"]] = piece["value"]
    major, minor, patch = pieces_dict["major"], pieces_dict["minor"], pieces_dict["patch"]

    # Render the version in the requested style.
    if style == "major":
        return str(major)
    elif style == "major.minor":
        return f"{major}.{minor}"
    elif style == "semver":
        return f"{major}.{minor}.{patch}"
    else:
        # This should never happen.
        raise RuntimeError("This should never happen")

