def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects: number of objects checked
        good_objects: number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    for _, obj in self.iteritems():
        if obj.type == "container":
            continue

        num_objects += 1

        # Check the JSON format of the object
        try:
            js = json.loads(obj.data)
        except ValueError:
            if show_warnings:
                warnings.warn("Object {0} has invalid JSON: {1}".format(obj.name, obj.data))
            continue

        # Check the object's hash
        if check_digests:
            hash_ = hashlib.sha256(obj.data).hexdigest()
            if hash_ != obj.hash:
                if show_warnings:
                    warnings.warn("Object {0} has a bad hash: {1} vs. {2}".format(obj.name, hash_, obj.hash))
                continue

        # Check the object's references
        for ref in obj.refs:
            if ref.type == "preceding":
                preceding_obj = self[ref.name]
                if preceding_obj.type == "container":
                    preceding_obj = preceding_obj.object
                if preceding_obj.name != ref.name or preceding_obj.hash != ref.hash:
                    if show_warnings:
                        warnings.warn("Object {0} has a bad reference: {1} vs. {2}".format(obj.name, ref.name, preceding_obj.name))
                    continue

        good_objects += 1

    return good_objects, num_objects

