def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        errors = []
        warning = []
        inventory_pkgs = {}
        diff_pkgs = []

        for version_dir in version_dirs:
            version_dir_path = os.path.join(self.backup_root, version_dir)
            inventory_path = os.path.join(version_dir_path, self.inventory_name)

            if not os.path.exists(inventory_path):
                errors.append(f"Inventory '{self.inventory_name}' not found in version '{version_dir}'.")
            else:
                with open(inventory_path, "r") as f:
                    inventory_data = json.load(f)

                inventory_pkgs[version_dir] = inventory_data
                diff_pkgs = [pkg for pkg in inventory_pkgs[version_dir] if pkg not in inventory_pkgs.get(version_dirs[0], [])]

                if len(diff_pkgs) > 0:
                    warning.append(f"Version {version_dir} has additional packages: {', '.join(diff_pkgs)}")

        if len(errors) > 0:
            return False, errors
        elif len(warning) > 0:
            return True, warning
        else:
            return True, None

