def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key in merged_nodes:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged_value = merged_nodes[key]
                if not isinstance(merged_value, ruamel.yaml.nodes.MappingNode):
                    merged_nodes[key] = value
                else:
                    merged_nodes[key] = deep_merge_nodes([merged_value, value])
            else:
                merged_nodes[key] = value
        else:
            merged_nodes[key] = value
    return list(merged_nodes.items())

def deep_merge_nodes(nodes):
    # First, group nodes by their scalar keys
    key_to_nodes = {}
    for node in nodes:
        key = node[0].value
        if key not in key_to_nodes:
            key_to_nodes[key] = []
        key_to_nodes[key].append(node)

    # Next, deep merge the nodes for each key
    result = []
    for key, key_nodes in key_to_nodes.items():
        merged_node = _deep_merge_nodes(key_nodes)
