def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for key, value in nodes:
        if key in seen_keys:
            # Look for an existing value with the same key and merge them
            for i, (k, v) in enumerate(result):
                if k == key:
                    merge_values = {v.value: v}
                    for v2 in value.value:
                        if v2.value in merge_values:
                            # Merge the values
