            >>> size_to_bytes("1K")
            1000
    """
    units = {"K": 1000, "M": 1000000, "G": 1000000000, "T": 1000000000000}
    size = size.upper()
    for unit, multiplier in units.items():
        if size.endswith(unit):
            return int(float(size[:-1]) * multiplier)
