def string_to_int(string: str, alphabet: List[str]) -> int:
    if not alphabet:
        raise ValueError("Alphabet must contain at least one element")
    if not string:
        return 0
    base = len(alphabet)
    exp = len(string) - 1
    result = 0
    for char in string:
        i = alphabet.index(char)
        result += (base ** exp) * i
        exp -= 1
    return result

