def make_find_paths(find_paths):
    find_paths_transformed = []
    for find_path in find_paths:
        if re.match(r'[:/]', find_path):
            # Pass through existing patterns untouched
            find_paths_transformed.append(find_path)
        else:
            # Transform path fragments into glob patterns
            find_paths_transformed.append(f'sh:**/*{find_path}*/**')
    return find_paths_transformed

