    if cwd and not os.path.exists(cwd):
        raise ValueError("Current working directory not found: {}".format(cwd))
    if env and not isinstance(env, dict):
        raise ValueError("Environment must be a dictionary")
    process = subprocess.Popen(commands + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.communicate()
    if process.returncode != 0:
        raise RuntimeWarning("Command failed with exit code {}: {}".format(process.returncode, " ".join(commands + args)))
    if verbose:
        print("Command succeeded: {}".format(" ".join(commands + args)))
    return stdout, stderr

