def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is not None:
        # Rescale the graph to the provided scale
        if self.x is not None:
            # Rescale the last coordinate
            self.x = other
        if self.y is not None:
            self.y = other
        if self.z is not None:
            self.z = other
        if self.err is not None:
            # Rescale the last error coordinate
            self.err = other
    else:
        # Return the scale of the graph
        if self.x is not None:
            return self.x
        if self.y is not None:
            return self.y
        if self.z is not None:
            return self.z
        if self.err is not None:
            return self.err
        else:
            raise ValueError("Cannot get the scale of the graph if all coordinates and errors are None")

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, numbers.Number):
        if self.scale == 0 or self.scale is None:
            raise ValueError("Unable to rescale graph with zero or unknown scale.")
        for field in self.fields:
            for error in field.errors:
                error.value = error.value * other / self.scale
        self.scale = other
    else:
        raise TypeError("Unable to rescale graph with object of type " + str(type(other)) + ".")

