def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content
    if get_coordinate == "left":
        get_coordinate = lambda bin_content: float(bin_content.split(" ")[0].lstrip("(").rstrip(")"))
    elif get_coordinate == "right":
        get_coordinate = lambda bin_content: float(bin_content.split(" ")[1].lstrip("(").rstrip(")"))
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_content: float(bin_content.split(" ")[1].lstrip("(").rstrip(")")) - float(bin_content.split(" ")[0].lstrip("(").rstrip(")"))
    else:
        raise ValueError("Invalid get_coordinate argument: {}".format(get_coordinate))
    graph = Graph()
    for field_name in field_names:
        if field_name not in hist.field_names:
            raise ValueError("Field name {} not found in histogram".format(field_name))
    for bin_content in hist.bins:
        graph.add_point(make_value(bin_content), get_coordinate(bin_content), name=field_names[0])
    graph.scale = scale if scale is not None else hist.scale
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not isinstance(hist, histogram.Histogram):
        raise TypeError("Argument hist must be a histogram.Histogram")
    if not callable(make_value) and make_value is not None:
        raise TypeError("Argument make_value must be a callable or None")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Argument get_coordinate must be one of 'left', 'right', 'middle'")
    if not isinstance(field_names, tuple):
        raise TypeError("Argument field_names must be a tuple")
    if scale is not None and not isinstance(scale, (int, float)):
        raise TypeError("Argument scale must be a number or None")

    dimension = hist.dimension
    if len(field_names) != dimension:
        raise ValueError("Argument field_names must have the same length as the histogram dimension")

    graph = graph.Graph(scale=scale or hist.scale, axis_names=hist.axis_names)
    graph.add_data(tuple(hist.axes[i].metadata.get("name", field_names[i] or "v" + str(i)) for i in range(dimension)))
    for bin_ in hist.bins:
        if make_value is None:
            value = bin_.value
        else:
            value = make_value(bin_)
        if not isinstance(value, tuple):
            value = (value,)
        if get_coordinate == "left":
            coordinate = bin_.left
        elif get_coordinate == "right":
            coordinate = bin_.right
        else:  # "middle"
            coordinate = (bin_.left + bin_.right) / 2
        graph.add_point(coordinate, value)

    return graph

