def determineMetaclass(bases: List[type], explicit_mc: type = None) -> type:
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclasses = [type(base) for base in bases]
    if explicit_mc:
        metaclasses.append(explicit_mc)
    if not metaclasses:
        return type
    if len(metaclasses) == 1:
        return metaclasses[0]
    ne_metaclasses = set(metaclasses)
    if len(ne_metaclasses) == 1:
        return ne_metaclasses.pop()
    for metaclass in metaclasses:
        if not issubclass(metaclass, tuple(ne_metaclasses - {metaclass})):
            return metaclass
    raise TypeError("Inconsistent metaclasses: %s" % ", ".join(metaclass.__name__ for metaclass in metaclasses))

