    if len(bases) == 0:
        return type
    if len(bases) == 1:
        return type(bases[0])
    if bases[0] is type(bases[1]):
        return type(bases[0])
    else:
        raise TypeError("Incompatible metaclasses: %r vs. %r" % (bases[0].__class__, bases[1].__class__))

