def verify_relayable_signature(public_key, doc, signature):
    """
    Verifies the signed XML elements to ensure the claimed author did
    actually generate this message.
    """
    try:
        # Get the signed XML elements
        signed_elements = signature.get_signed_info_elements()

        # Verify the elements using the provided public key
        for element in signed_elements:
            verified = element.verify(public_key)
            if not verified:
                raise InvalidSignatureError()
    except InvalidSignatureError:
        raise InvalidSignatureError()

