def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """

    # Get all settings directories
    settings_dir_list = settings_dirs.split(":")

    # Loop through each directory and find ini files
    ini_files = []
    for settings_dir in settings_dir_list:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(".ini"):
                    ini_files.append(os.path.join(root, file))

    # Filter ini files based on spec_option
    if spec_option == "python":
