    else:
        raise ValueError("Invalid spec_option value")

    # Create a new IniType complex type
    IniType = createcomplex(settings_dirs)
    IniType.Name = "Ini"

    # Add ini files as children to the IniType complex type
    for ini_file in ini_files:
        IniFile = IniType.new(Name=os.path.basename(ini_file), Value=ini_file)
        IniType.add(IniFile)

    return IniType

