def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise InvalidYAMLFileError: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("YAML file is required")

    try:
        with open(yaml_file, "r") as stream:
            data = yaml.safe_load(stream)
    except OSError:
        raise IOException("Could not open YAML file for reading")

    for mandatory_key in cls.MANDATORY_KEYS:
        if mandatory_key not in data:
            raise InvalidYAMLFileError("Mandatory key {} is missing from the YAML file".format(mandatory_key))

    return data

